-- ====================================================================
-- GAADHE KOSHA (ಗಾದೆ ಕೋಶ) - PROVERB SEED BATCH 2
-- Records: 501 to 1000 of 2868
-- ====================================================================

INSERT INTO public.proverbs (
    kannada, transliteration, english_meaning, kannada_meaning,
    category, category_kn, situation, situation_kn, tags, contributor, likes, is_verified
) VALUES
    ('ಆಲಸಿ-ಮುಂಡೇದ್ಕೆ ಎರಡು ಖರ್ಚು, ಲೋಭಿ-ಮುಂಡೇದ್ಕೆ ಮೂರು ಖರ್ಚು', 'Aalasi-mumdeedke eradu kharchu, loobhi-mumdeedke mooru kharchu', '[Translation in progress] Traditional folk wisdom: "ಆಲಸಿ-ಮುಂಡೇದ್ಕೆ ಎರಡು ಖರ್ಚು, ಲೋಭಿ-ಮುಂಡೇದ್ಕೆ ಮೂರು ಖರ್ಚು". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಆಲಸಿ-ಮುಂಡೇದ್ಕೆ ಎರಡು ಖರ್ಚು, ಲೋಭಿ-ಮುಂಡೇದ್ಕೆ ಮೂರು ಖರ್ಚು". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಆಲಸಿಮುಂಡೇದ್ಕೆ","ಎರಡು","ಖರ್ಚು","ಲೋಭಿಮುಂಡೇದ್ಕೆ","ಮೂರು","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತುಂಬೆ ಗಿಡಕ್ಕೆ ಏಣಿ ಹಾಕಿದಂತೆ', 'Tumbe gidakke eeni haakidamte', '[Translation in progress] Traditional folk wisdom: "ತುಂಬೆ ಗಿಡಕ್ಕೆ ಏಣಿ ಹಾಕಿದಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತುಂಬೆ ಗಿಡಕ್ಕೆ ಏಣಿ ಹಾಕಿದಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತುಂಬೆ","ಗಿಡಕ್ಕೆ","ಏಣಿ","ಹಾಕಿದಂತೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ದುಡ್ಡೇ ದೊಡ್ಡಪ್ಪ,ಬುದ್ಧಿ ಅದರಪ್ಪ', 'Duddee doddappa,buddhi adarappa', '[Translation in progress] Traditional folk wisdom: "ದುಡ್ಡೇ ದೊಡ್ಡಪ್ಪ,ಬುದ್ಧಿ ಅದರಪ್ಪ". Context: Guidance on education and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ದುಡ್ಡೇ ದೊಡ್ಡಪ್ಪ,ಬುದ್ಧಿ ಅದರಪ್ಪ". ಇದು ಶಿಕ್ಷಣ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'education', 'ಶಿಕ್ಷಣ', 'Used in daily conversations to illustrate education principles and life lessons.', 'ಶಿಕ್ಷಣ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ದುಡ್ಡೇ","ದೊಡ್ಡಪ್ಪಬುದ್ಧಿ","ಅದರಪ್ಪ","ಶಿಕ್ಷಣ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕಾಲಿಗೆ ಬಿದ್ದು ಕಾಲುಂಗರ ಬಿಚ್ಚಿಕೊಂಡರಂತೆ', 'Kaalige biddu kaalumgara bichchikomdaramte', '[Translation in progress] Traditional folk wisdom: "ಕಾಲಿಗೆ ಬಿದ್ದು ಕಾಲುಂಗರ ಬಿಚ್ಚಿಕೊಂಡರಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕಾಲಿಗೆ ಬಿದ್ದು ಕಾಲುಂಗರ ಬಿಚ್ಚಿಕೊಂಡರಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕಾಲಿಗೆ","ಬಿದ್ದು","ಕಾಲುಂಗರ","ಬಿಚ್ಚಿಕೊಂಡರಂತೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅಪ್ಪನ ಕಾಲಕ್ಕೆ ಅರಮನೆ, ಮಗನ ಕಾಲಕ್ಕೆ ಬರೀಮನೆ', 'Appana kaalakke aramane, magana kaalakke bareemane', '[Translation in progress] Traditional folk wisdom: "ಅಪ್ಪನ ಕಾಲಕ್ಕೆ ಅರಮನೆ, ಮಗನ ಕಾಲಕ್ಕೆ ಬರೀಮನೆ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅಪ್ಪನ ಕಾಲಕ್ಕೆ ಅರಮನೆ, ಮಗನ ಕಾಲಕ್ಕೆ ಬರೀಮನೆ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅಪ್ಪನ","ಕಾಲಕ್ಕೆ","ಅರಮನೆ","ಮಗನ","ಬರೀಮನೆ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ವೇದ ಸುಳ್ಳಾದ್ರು ಗಾದೆ ಸುಳ್ಳಲ್ಲ', 'Veeda sullaadru gaade sullalla', '[Translation in progress] Traditional folk wisdom: "ವೇದ ಸುಳ್ಳಾದ್ರು ಗಾದೆ ಸುಳ್ಳಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ವೇದ ಸುಳ್ಳಾದ್ರು ಗಾದೆ ಸುಳ್ಳಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ವೇದ","ಸುಳ್ಳಾದ್ರು","ಗಾದೆ","ಸುಳ್ಳಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಇಲ್ಲದ ಬದುಕು ಮಾಡಿ ಇಲಿಗೆ ಚಣ್ಣ ಹೊಲಿಸಿದರು', 'Illada baduku maadi ilige channa holisidaru', '[Translation in progress] Traditional folk wisdom: "ಇಲ್ಲದ ಬದುಕು ಮಾಡಿ ಇಲಿಗೆ ಚಣ್ಣ ಹೊಲಿಸಿದರು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಇಲ್ಲದ ಬದುಕು ಮಾಡಿ ಇಲಿಗೆ ಚಣ್ಣ ಹೊಲಿಸಿದರು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಇಲ್ಲದ","ಬದುಕು","ಮಾಡಿ","ಇಲಿಗೆ","ಚಣ್ಣ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತಲೇ ಕೂದಲು ಉದ್ದವಿದ್ದವಳು ಹ್ಯಾಗೆ ಕಟ್ಟಿದರೂ ಚಂದ', 'Talee koodalu uddaviddavalu hyaage kattidaroo chamda', '[Translation in progress] Traditional folk wisdom: "ತಲೇ ಕೂದಲು ಉದ್ದವಿದ್ದವಳು ಹ್ಯಾಗೆ ಕಟ್ಟಿದರೂ ಚಂದ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತಲೇ ಕೂದಲು ಉದ್ದವಿದ್ದವಳು ಹ್ಯಾಗೆ ಕಟ್ಟಿದರೂ ಚಂದ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತಲೇ","ಕೂದಲು","ಉದ್ದವಿದ್ದವಳು","ಹ್ಯಾಗೆ","ಕಟ್ಟಿದರೂ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ದುಡ್ಡಿಗೆ ದುಡ್ಡು ಗಂಟು ಹಾಕಿದ್ಯೋ? ಬೆನ್ನಿಗೆ ಹೊಟ್ಟೆ ಅಂಟು ಹಾಕಿದ್ಯೋ', 'Duddige duddu gamtu haakidyoo? bennige hotte amtu haakidyoo', '[Translation in progress] Traditional folk wisdom: "ದುಡ್ಡಿಗೆ ದುಡ್ಡು ಗಂಟು ಹಾಕಿದ್ಯೋ? ಬೆನ್ನಿಗೆ ಹೊಟ್ಟೆ ಅಂಟು ಹಾಕಿದ್ಯೋ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ದುಡ್ಡಿಗೆ ದುಡ್ಡು ಗಂಟು ಹಾಕಿದ್ಯೋ? ಬೆನ್ನಿಗೆ ಹೊಟ್ಟೆ ಅಂಟು ಹಾಕಿದ್ಯೋ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ದುಡ್ಡಿಗೆ","ದುಡ್ಡು","ಗಂಟು","ಹಾಕಿದ್ಯೋ","ಬೆನ್ನಿಗೆ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹಲವು ಸಲ ಸಾಯುವವನು ಹೇಡಿ,ವೀರಯೋಧನಿಗೊಂದೇ ಸಲ ಸಾವು', 'Halavu sala saayuvavanu heedi,veerayoodhanigomdee sala saavu', '[Translation in progress] Traditional folk wisdom: "ಹಲವು ಸಲ ಸಾಯುವವನು ಹೇಡಿ,ವೀರಯೋಧನಿಗೊಂದೇ ಸಲ ಸಾವು". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹಲವು ಸಲ ಸಾಯುವವನು ಹೇಡಿ,ವೀರಯೋಧನಿಗೊಂದೇ ಸಲ ಸಾವು". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹಲವು","ಸಾಯುವವನು","ಹೇಡಿವೀರಯೋಧನಿಗೊಂದೇ","ಸಾವು","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬೆಳ್ಳಯ್ಯ ಕಾಕಾ ಅರಿವಯ್ಯ ಮೂಕ', 'Bellayya kaakaa arivayya mooka', '[Translation in progress] Traditional folk wisdom: "ಬೆಳ್ಳಯ್ಯ ಕಾಕಾ ಅರಿವಯ್ಯ ಮೂಕ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬೆಳ್ಳಯ್ಯ ಕಾಕಾ ಅರಿವಯ್ಯ ಮೂಕ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬೆಳ್ಳಯ್ಯ","ಕಾಕಾ","ಅರಿವಯ್ಯ","ಮೂಕ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಆರಿದೋಗರಕ್ಕೆ ಮೊಸರಿಕ್ಕಿ ಕಾಗೆಗೆ ಸೂರೆಕೊಟ್ಟರು', 'Aaridoogarakke mosarikki kaagege soorekottaru', '[Translation in progress] Traditional folk wisdom: "ಆರಿದೋಗರಕ್ಕೆ ಮೊಸರಿಕ್ಕಿ ಕಾಗೆಗೆ ಸೂರೆಕೊಟ್ಟರು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಆರಿದೋಗರಕ್ಕೆ ಮೊಸರಿಕ್ಕಿ ಕಾಗೆಗೆ ಸೂರೆಕೊಟ್ಟರು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಆರಿದೋಗರಕ್ಕೆ","ಮೊಸರಿಕ್ಕಿ","ಕಾಗೆಗೆ","ಸೂರೆಕೊಟ್ಟರು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
